import { HttpClient, HttpParams } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { FundamentacaoLegalModel } from "../models/fundamentacao-legal.model";
import { environment } from "../../environments/environment";

@Injectable({
    providedIn: 'root'
})
export class DiversosService {

    private baseUrl = environment.APIEndpoint;

    constructor(private http: HttpClient) {}

    obterUrl(platform: string): Observable<any> {
        let params: HttpParams = new HttpParams();
        params = params.append('platform', platform);
        return this.http.get<any>(`${this.baseUrl}/calculadora/download/url`, {params: params});
    }

}
